sp_widget.client_script:
api.controller = function($scope, $location) {
  $scope.c = this;
  $scope.c.tab = 'tasks'; // Default tab

  // Set current tab
  $scope.c.setTab = function(tabName) {
    $scope.c.tab = tabName;
  };

  // View Record (can be redirected to another widget or form)
 $scope.c.viewRecord = function(record) {
  window.location.href = '/emp?id=form&table=x_1790116_event_ma_task&sys_id=' + record.sys_id + '&view=sp';
};


 // Edit Record
$scope.c.editRecord = function(record) {
