};

// Edit Attendee
$scope.c.editAttendee = function(record) {
  window.location.href = '/emp?id=form&table=x_1790116_event_ma_attendee&sys_id=' + record.sys_id + '&view=sp';
};





// View Vendor
$scope.c.viewVendor = function(record) {
  window.location.href = '/emp?id=form&table=x_1790116_event_ma_vendor&sys_id=' + record.sys_id + '&view=sp';
};

// Edit Vendor
$scope.c.editVendor = function(record) {
  window.location.href = '/emp?id=form&table=x_1790116_event_ma_vendor&sys_id=' + record.sys_id + '&view=sp';
};








		$scope.c.viewschedule = function(record) {
  window.location.href = '/emp?id=form&table=x_1790116_event_ma_schedule&sys_id=' + record.sys_id + '&view=sp';
};

// Edit Vendor
$scope.c.editschedule = function(record) {
  window.location.href = '/emp?id=form&table=x_1790116_event_ma_schedule&sys_id=' + record.sys_id + '&view=sp';
};






	$scope.c.viewbudget = function(record) {
  window.location.href = '/emp?id=form&table=x_1790116_event_ma_budget&sys_id=' + record.sys_id + '&view=sp';
};

// Edit Vendor
$scope.c.editbudget = function(record) {
  window.location.href = '/emp?id=form&table=x_1790116_event_ma_budget&sys_id=' + record.sys_id + '&view=sp';
};







	$scope.c.viewFeedback = function(record) {
  window.location.href = '/emp?id=form&table=x_1790116_event_ma_feedback&sys_id=' + record.sys_id + '&view=sp';
};

// Edit Vendor
$scope.c.editfeedback = function(record) {
  window.location.href = '/emp?id=form&table=x_1790116_event_ma_feedback&sys_id=' + record.sys_id + '&view=sp';
};










































 $scope.c = $scope.c || {};

$scope.c.deleteRecord = function(recordSysId) {
  if (confirm("Are you sure you want to delete this task?")) {
    $scope.server.update({
      action: 'delete_task',
      sys_id: recordSysId
    }).then(function(response) {
      if (response.success) {
        alert("Task deleted successfully.");
        $scope.server.get(); // reload data
      } else {
        alert("Failed to delete task: " + (response.error || 'Unknown error'));
      }
    });
  }
};





};

sp_widget.css:
/* Action Buttons */
.action-btn {
  margin-right: 5px;
  border-radius: 5px;
  padding: 5px 10px;
  font-size: 13px;
}

.action-btn.view {
  background-color: #2196f3;
  color: white;
  border: none;
}

.action-btn.edit {
  background-color: #ffc107;
  color: black;
  border: none;
}

.action-btn.delete {
  background-color: #f44336;
  color: white;
  border: none;
}

.action-btn:hover {
  transform: scale(1.05);
  opacity: 0.95;
  cursor: pointer;
}

/* Optional: Space the action column */
.table td.actions-cell {
  white-space: nowrap;
}

sp_widget.script:
(function() {
  // ✅ Handle Delete Action
  // Delete logic
// DELETE logic for task
// Delete Task Record
if (input && input.action === 'delete_task' && input.sys_id) {
  var taskGR = new GlideRecord('table_name');
  if (taskGR.get(input.sys_id)) {
    try {
      taskGR.deleteRecord();
      data.success = true;
    } catch (e) {
      data.success = false;
      data.error = 'Exception during deletion: ' + e.message;
    }
  } else {
    data.success = false;
    data.error = 'Task not found';
  }
  return;
}




  // Begin regular data loading
  data.event = {};
  data.tasks = [];
  data.attendees = [];
  data.vendors = [];
  data.budget = [];
  data.schedule = [];
  data.feedback = [];

  var sysId = (typeof input !== 'undefined' && input.sys_id) || $sp.getParameter('sys_id');
  if (!sysId) {
    data.error = "No Event ID provided.";
    return;
  }

  // Fetch Event Info
  var evGR = new GlideRecord('x_1790116_event_ma_event');
  if (evGR.get(sysId)) {
    data.event = {
      sys_id: evGR.getUniqueValue(),
      name: evGR.getValue('u_event_name'),
      date: evGR.getDisplayValue('u_event_date'),
      location: evGR.getValue('u_event_location'),
      status: evGR.getDisplayValue('u_status'),
      contact_person: evGR.getValue('u_contact_person'),
      contact_number: evGR.getValue('u_contact_number'),
      email: evGR.getValue('u_email')
    };
  } else {
    data.error = "Event not found.";
    return;
  }

  // Tasks
  var taskGR = new GlideRecord('x_1790116_event_ma_task');
  taskGR.addQuery('u_event_id', sysId);
  taskGR.query();
  while (taskGR.next()) {
    data.tasks.push({
      sys_id: taskGR.getUniqueValue(),
      name: taskGR.getValue('u_task_name'),
      assigned_to: taskGR.getDisplayValue('u_assigned_to'),
      due_date: taskGR.getDisplayValue('u_due_date'),
      status: taskGR.getDisplayValue('u_status')
    });
  }

  // Attendees
  var attGR = new GlideRecord('x_1790116_event_ma_attendee');
  attGR.addQuery('u_event_id', sysId);
  attGR.query();
  while (attGR.next()) {
    data.attendees.push({
      sys_id: attGR.getUniqueValue(),
      first_name: attGR.getValue('u_first_name'),
      last_name: attGR.getValue('u_last_name'),
      email: attGR.getValue('u_email'),
      phone: attGR.getValue('u_contact_number'),
      status: attGR.getDisplayValue('u_status')
    });
  }

  // Vendors
  var venGR = new GlideRecord('x_1790116_event_ma_vendor');
  venGR.addQuery('u_event_id', sysId);
  venGR.query();
  while (venGR.next()) {
    data.vendors.push({
      sys_id: venGR.getUniqueValue(),
      name: venGR.getValue('u_vendor_name'),
      contact: venGR.getValue('u_contact_person'),
      phone: venGR.getValue('u_contact_number'),
      services: venGR.getValue('u_services_provided')
    });
  }

  // Budget
  var budGR = new GlideRecord('x_1790116_event_ma_budget');
  budGR.addQuery('u_event_id', sysId);
  budGR.query();
  while (budGR.next()) {
    data.budget.push({
      sys_id: budGR.getUniqueValue(),
      total_budget: budGR.getDisplayValue('u_total_budget'),
      amount_spent: budGR.getDisplayValue('u_amount_spent'),
      remaining: budGR.getDisplayValue('u_amount_remaining'),
      status: budGR.getDisplayValue('u_status')
    });
  }

  // Schedule
  var schGR = new GlideRecord('x_1790116_event_ma_schedule');
  schGR.addQuery('u_event_id', sysId);
  schGR.orderBy('u_start_time');
  schGR.query();
  while (schGR.next()) {
    data.schedule.push({
      sys_id: schGR.getUniqueValue(),
      activity: schGR.getValue('u_activity_name'),
      start: schGR.getDisplayValue('u_start_time'),
      end: schGR.getDisplayValue('u_end_time'),
      location: schGR.getValue('u_location')
    });
  }

  // Feedback
  var fbGR = new GlideRecord('x_1790116_event_ma_feedback');
  fbGR.addQuery('u_event_id', sysId);
  fbGR.query();
  while (fbGR.next()) {
    data.feedback.push({
      sys_id: fbGR.getUniqueValue(),
      attendee: fbGR.getDisplayValue('u_attendee_id'),
      rating: fbGR.getDisplayValue('u_rating'),
      comments: fbGR.getValue('u_comments')
    });
  }
})();
